ALTER TABLE public.payments DROP CONSTRAINT payments_status_check;
ALTER TABLE public.payments ADD CONSTRAINT payments_status_check CHECK(status IN('pending','success','failed','needs_review'));
CREATE OR REPLACE FUNCTION public.create_p2p_listing(_side text,_mvt numeric,_price numeric) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); result uuid; bal numeric; BEGIN IF uid IS NULL OR _side<>'sell' OR _mvt IS NULL OR _price IS NULL OR _mvt<=0 OR _price<=0 THEN RAISE EXCEPTION 'Invalid listing'; END IF; PERFORM pg_advisory_xact_lock(hashtext('market'||uid::text)); IF EXISTS(SELECT 1 FROM public.profiles WHERE id=uid AND marketplace_blocked) THEN RAISE EXCEPTION 'Marketplace access suspended'; END IF; SELECT coalesce(sum(amount),0) INTO bal FROM public.ledger_entries WHERE user_id=uid AND account='tradable_mvt' AND status='confirmed'; IF bal<_mvt THEN RAISE EXCEPTION 'Not enough tradable MVG'; END IF; INSERT INTO public.p2p_listings(user_id,side,mvt_amount,price_usd) VALUES(uid,'sell',_mvt,_price) RETURNING id INTO result; INSERT INTO public.ledger_entries(user_id,account,amount,kind,reference) VALUES(uid,'tradable_mvt',-_mvt,'p2p_escrow','POST-'||result||'-debit'),(uid,'p2p_escrow',_mvt,'p2p_escrow','POST-'||result||'-escrow'); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.create_p2p_listing(text,numeric,numeric) FROM public,anon; GRANT EXECUTE ON FUNCTION public.create_p2p_listing(text,numeric,numeric) TO authenticated;
CREATE OR REPLACE FUNCTION public.convert_mvt(_mvt numeric) RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); avail numeric; ref text; BEGIN IF uid IS NULL OR _mvt IS NULL OR _mvt<=0 THEN RAISE EXCEPTION 'Enter a positive amount'; END IF; PERFORM pg_advisory_xact_lock(hashtext('market'||uid::text)); SELECT coalesce(sum(amount),0) INTO avail FROM public.ledger_entries WHERE user_id=uid AND account='mvt' AND status='confirmed'; IF _mvt>avail THEN RAISE EXCEPTION 'Not enough confirmed MVG'; END IF; ref:='CONV-'||gen_random_uuid(); INSERT INTO public.ledger_entries(user_id,account,amount,kind,reference) VALUES(uid,'mvt',-_mvt,'convert',ref||'-from'),(uid,'tradable_mvt',_mvt,'convert',ref||'-to'); RETURN json_build_object('converted',_mvt); END $$;
REVOKE ALL ON FUNCTION public.convert_mvt(numeric) FROM public,anon; GRANT EXECUTE ON FUNCTION public.convert_mvt(numeric) TO authenticated;